package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public class AutoDownloadActivity extends Activity {
 private LinearLayout root,rows;private final Handler h=new Handler(Looper.getMainLooper());private final Runnable refresh=new Runnable(){public void run(){drawRows();h.postDelayed(this,5000);}};
 private int dp(int n){return SoundFlowUi.dp(this,n);}private TextView text(String s,int size,boolean bold){return SoundFlowUi.text(this,s,size,bold?SoundFlowUi.TEXT:SoundFlowUi.MUTED,bold);}
 private void gap(LinearLayout c,int n){SoundFlowUi.gap(c,n);}private TextView button(String s,boolean primary,Runnable r){return SoundFlowUi.button(this,s,primary,r);}
 public void onCreate(Bundle b){super.onCreate(b);ResidentChecks.start(this);getWindow().setStatusBarColor(SoundFlowUi.BG);getWindow().setNavigationBarColor(SoundFlowUi.BG);root=SoundFlowUi.column(this);root.setBackgroundColor(SoundFlowUi.BG);root.setPadding(dp(20),dp(8),dp(20),dp(12));if(Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets s=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(s.left+dp(20),s.top+dp(8),s.right+dp(20),s.bottom+dp(12));return i;});setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(button("‹",false,this::finish),new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=text("Загрузки",28,true);title.setPadding(dp(16),0,0,0);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);gap(root,20);root.addView(text("Активные очереди, автозагрузки и ошибки. Завершённые разовые загрузки скрываются, треки остаются в «Офлайн».",15,false));gap(root,12);root.addView(button("Проверить очереди",true,()->{int started=AutoDownloads.startVisible(this);drawRows();SoundFlowUi.notice(this,started>0?"Проверка очередей запланирована без уведомления":AutoDownloads.allowed(this)?"Очереди проверены; активная загрузка продолжается либо ожидается запуск Android":AutoDownloads.waitReason(this));}));gap(root,16);ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);rows=SoundFlowUi.column(this);scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));Motion.enter(root);}
 protected void onStart(){super.onStart();AutoDownloads.schedule(this);AutoDownloads.retry(this);h.post(refresh);}protected void onStop(){h.removeCallbacks(refresh);super.onStop();}protected void onDestroy(){h.removeCallbacksAndMessages(null);super.onDestroy();}
 private void drawRows(){rows.removeAllViews();String user=DownloadSync.owner(this);try(SyncDb db=new SyncDb(this)){ArrayList<JSONObject> plans=db.workPlans(user);if(plans.isEmpty())rows.addView(text("Нет активных загрузок. Автозагрузка включается прямо в «Любимом» или внутри плейлиста.",16,false));for(JSONObject p:plans){String id=p.optString("id"),name=p.optString("title"),kind=p.optString("kind");int[] n=db.totals(user,id);LinearLayout card=SoundFlowUi.card(this);card.addView(text(name,21,true));gap(card,8);card.addView(text(!p.optBoolean("listed")?"Список ещё не получен":n[0]==0?"В списке пока нет треков":n[1]+" из "+n[0]+" на устройстве",16,true));gap(card,8);ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(!p.optBoolean("listed"));progress.setMax(Math.max(1,n[0]));progress.setProgress(n[1]);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(SoundFlowUi.ACCENT));card.addView(progress,new LinearLayout.LayoutParams(-1,dp(6)));gap(card,12);card.addView(text("Ожидают/повтор: "+n[3]+" · Отказы: "+n[2],14,false));gap(card,8);card.addView(text(p.optString("status"),14,false));gap(card,12);if(p.optBoolean("auto"))card.addView(text("Автозагрузка включена · переключатель внутри списка",14,false));if(n[2]>0||n[3]>0){gap(card,8);card.addView(button("Причины отказов",false,()->details(user,id,name)));gap(card,8);card.addView(button("Продолжить / повторить ошибки",false,()->resumePlan(user,id,name,kind)));}rows.addView(card,new LinearLayout.LayoutParams(-1,-2));gap(rows,16);}}}
 private void resumePlan(String user,String id,String name,String kind){ArrayList<JSONObject> errors;try(SyncDb db=new SyncDb(this)){errors=db.failures(user,id);}if(errors.isEmpty()){DownloadActions.start(this,id,name,kind,false,true);return;}String[] labels=new String[errors.size()+1];labels[0]="Все ошибки и незавершённые треки";for(int i=0;i<errors.size();i++)labels[i+1]=errors.get(i).optString("title");new AlertDialog.Builder(this).setTitle("Что продолжить?").setItems(labels,(d,index)->{if(index==0){DownloadActions.start(this,id,name,kind,false,true);return;}String tid=errors.get(index-1).optString("id");try(SyncDb db=new SyncDb(this)){for(Library.Track t:db.tracks(user,id))if(tid.equals(t.id())){Library library=new Library(this);library.upsert(t);library.save();DownloadActions.start(this,"track:"+tid,t.title,"track",true,true);return;}}}).setNegativeButton("Отмена",null).show();}
 private void details(String user,String id,String title){ArrayList<JSONObject> errors;try(SyncDb db=new SyncDb(this)){errors=db.failures(user,id);}StringBuilder report=new StringBuilder("Волна "+Motion.version(this)+" · "+title+"\n");for(JSONObject e:errors)report.append("\n").append(e.optString("title")).append(" [").append(e.optString("id")).append("]\n").append(DownloadFault.label(e.optString("code"))).append(" · ").append(e.optString("code")).append("\n");if(errors.isEmpty())report.append("Нет записанных отказов. Незавершённые треки ожидают очереди.");TextView detail=text(report.toString(),15,false);detail.setPadding(dp(20),dp(12),dp(20),dp(12));ScrollView scroll=new ScrollView(this);scroll.addView(detail);new AlertDialog.Builder(this).setTitle("Причины по трекам").setView(scroll).setNegativeButton("Закрыть",null).setPositiveButton("Скопировать отчёт",(d,w)->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Диагностика загрузок",report.toString()));SoundFlowUi.notice(this,"Отчёт скопирован без токенов и адресов аудио");}).show();}
}
